import { Request, Response } from 'express';
import { PlaceOrderUseCase } from '../application/PlaceOrderUseCase';
import { UpdateOrderStateUseCase } from '../application/UpdateOrderStateUseCase';
import { CancelOrderUseCase } from '../application/CancelOrderUseCase';
import { ListOrdersByStateUseCase } from '../application/ListOrdersByStateUseCase';
import { OrderStateType } from '../domain/OrderState';

export class OrderController {
  constructor(
    private placeOrderUseCase: PlaceOrderUseCase,
    private updateOrderStateUseCase: UpdateOrderStateUseCase,
    private cancelOrderUseCase: CancelOrderUseCase,
    private listOrdersByStateUseCase: ListOrdersByStateUseCase,
  ) {}

  placeOrder = (req: Request, res: Response): void => {
    try {
      const orderId = this.placeOrderUseCase.execute(req.body);
      res.status(201).json({ orderId });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  };

  updateOrderState = (req: Request, res: Response): void => {
    try {
      const { orderId } = req.params;
      const stateValue = req.body.state;

      if (typeof stateValue !== 'string' && !Array.isArray(stateValue)) {
        res.status(400).json({ error: 'State is required and must be a string' });
        return;
      }

      this.updateOrderStateUseCase.execute(orderId, stateValue);
      res.status(200).json({ success: true });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  };

  cancelOrder = (req: Request, res: Response): void => {
    try {
      const { orderId } = req.params;
      this.cancelOrderUseCase.execute(orderId);
      res.status(200).json({ success: true });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  };

  listByState = (req: Request, res: Response): void => {
    try {
      const stateValue = req.query.state;

      if (!stateValue || (typeof stateValue !== 'string' && !Array.isArray(stateValue))) {
        res.status(400).json({ error: 'State query parameter is required' });
        return;
      }

      const orders = this.listOrdersByStateUseCase.execute(stateValue);
      res.status(200).json(orders);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  };
}

